<?php
$page_title='Bookings'; require_once __DIR__.'/../../config/database.php'; require_once __DIR__.'/../../config/session.php'; require_once __DIR__.'/../../config/functions.php'; require_once __DIR__.'/../../config/auth.php'; requireAdmin();
if($_SERVER['REQUEST_METHOD']==='POST'){ $id=(int)($_POST['id']??0);$status=$_POST['status']??'';if($id&&in_array($status,['pending','approved','rejected','completed','cancelled'],true)){$stmt=$pdo->prepare('UPDATE bookings SET status=? WHERE id=?');$stmt->execute([$status,$id]);} }
$bookings=$pdo->query("SELECT b.*,f.full_name AS fresher_name,s.title,s.scheduled_at,m.full_name AS mentor_name FROM bookings b JOIN users f ON f.id=b.fresher_id JOIN sessions s ON s.id=b.session_id JOIN users m ON m.id=s.mentor_id ORDER BY b.created_at DESC")->fetchAll();
?>
<?php include __DIR__.'/../includes/header.php'; ?><div class="admin-shell"><?php include __DIR__.'/../includes/sidebar.php'; ?><main class="admin-main"><div class="admin-topbar"><div><h1 class="admin-title">Bookings</h1><p class="admin-subtitle">Review and update learner booking requests.</p></div></div><div class="admin-card admin-table-wrap"><table class="admin-table"><thead><tr><th>Learner</th><th>Session</th><th>Mentor</th><th>Date</th><th>Status</th><th>Update</th></tr></thead><tbody><?php foreach($bookings as $booking): ?><tr><td><?php echo htmlspecialchars($booking['fresher_name']); ?></td><td><?php echo htmlspecialchars($booking['title']); ?></td><td><?php echo htmlspecialchars($booking['mentor_name']); ?></td><td><?php echo htmlspecialchars(date('M d, Y h:i A',strtotime($booking['scheduled_at']))); ?></td><td><span class="badge bg-secondary"><?php echo ucfirst($booking['status']); ?></span></td><td><form method="POST" class="d-flex gap-2"><input type="hidden" name="id" value="<?php echo $booking['id']; ?>"><select name="status" class="form-select form-select-sm"><option value="pending">Pending</option><option value="approved">Approved</option><option value="rejected">Rejected</option><option value="completed">Completed</option><option value="cancelled">Cancelled</option></select><button class="btn btn-sm btn-primary">Save</button></form></td></tr><?php endforeach; ?><?php if(!$bookings): ?><tr><td colspan="6" class="text-center text-muted py-4">No bookings found.</td></tr><?php endif; ?></tbody></table></div></main></div><?php include __DIR__.'/../includes/footer.php'; ?>
